// The shape of reports/results.json, as far as the dashboard reads it. Generated by `stc report`.

export const POLICIES = ['static', 'auto', 'symbolic'] as const;
export type Policy = (typeof POLICIES)[number];

export interface Row {
  workload: string;
  policy: Policy;
  calls: number;
  distinct_shapes: number;
  compiles: number;
  compile_ms: number;
  prologue_us_per_call: number;
  eager_ms: number;
  compiled_ms: number;
  max_abs_diff: number;
}

export interface Fuzz {
  workload: string;
  policy: Policy;
  draws: number;
  eager_ok: number;
  accepted: number;
  violations: number;
  coverage: number;
}

export interface Necessity {
  check: string;
  without_it: 'wrong results' | 'errors' | 'none seen';
}

export interface Example {
  prologue_checks: string;
  computation: string;
  guards: string[];
  symbols: string[];
  inputs: number;
  nodes: number;
}

export interface ProgramRow {
  program: string;
  about: string;
  calls: number;
  policies: Record<Policy, { compiles: number; wrong_calls: number; unsupported: string | null }>;
  fuzz?: { violations: number; draws: number; coverage: number };
}

export interface HeldSet {
  status: string;
  recorded_at: string | null;
  blind_first_run: boolean;
  rerun: { supported: number; wrong_or_violations: number };
  programs: number;
  supported: number;
  wrong_or_violations: number;
  static_compiles: number;
  auto_compiles: number;
  symbolic_compiles: number;
  calls: number;
  rows: ProgramRow[];
}

export interface ThunderRow {
  workload: string;
  system: string;
  calls: number;
  distinct_shapes: number;
  compiles: number;
  wall_s: number;
  max_abs_diff: number;
  error: string | null;
}

export interface Check {
  name: string;
  op: string;
  value: number;
  actual: number | null;
  ok: boolean;
}

export interface Results {
  generated_at: string;
  profile: string;
  workloads?: Record<string, { about: string; model: string }>;
  rows?: Row[];
  fuzz?: Fuzz[];
  necessity?: Record<string, Necessity[]>;
  summary?: {
    calls: number;
    static_compiles: number;
    symbolic_compiles: number;
    fuzz_draws: number;
    fuzz_violations: number;
    max_abs_diff: number;
  };
  sets?: Record<string, HeldSet>;
  thunder?: {
    meta: { torch: string; thunder: string; scale: number; machine: string };
    rows: ThunderRow[];
    run?: string;
    commit?: string;
  };
  examples?: Record<string, Example>;
  gate?: { floors: Check[]; targets: Check[] };
}

export function isResults(x: unknown): x is Results {
  if (typeof x !== 'object' || x === null) return false;
  const r = x as Record<string, unknown>;
  return typeof r.generated_at === 'string' && typeof r.profile === 'string';
}

/** compile counts for one workload, by policy */
export function byPolicy(rows: Row[], workload: string): Partial<Record<Policy, Row>> {
  const out: Partial<Record<Policy, Row>> = {};
  for (const r of rows) if (r.workload === workload) out[r.policy] = r;
  return out;
}
